    print(json.load(open(sys.argv[1])).get("server",{}).get("port",7861))
except Exception:
    print(7861)' "$AUDIOBOOK_STUDIO_HOME/config/settings.json"
}
pid_alive() { [ -n "${1:-}" ] && kill -0 "$1" 2>/dev/null; }
